'use client'

import gsap from 'gsap'
import type { ReactNode } from 'react'
import { createTransition } from './transition-core'
import './transitions.css'

/**
 * Fold-away.
 *
 * A sheet of paper unfolds across the screen, the route swaps behind it, then it
 * folds itself back down into a strip and drops off the edge.
 *
 * The panels are *nested*, not stacked — each one hinges off the top edge of the
 * one below it inside a shared `preserve-3d` context. That is what makes it a
 * real fold rather than a row of independent flips: rotating a panel carries
 * every panel above it, so the sheet collapses onto itself the way folded paper
 * actually does. Folding the deepest crease first and unfolding the shallowest
 * first is the same order your hands would use.
 *
 *   // app/layout.tsx
 *   <FoldAwayTransition panels={4}>{children}</FoldAwayTransition>
 */
export type FoldAwayOptions = {
  /** Which edge the sheet folds down to and leaves through. */
  direction: 'bottom' | 'top' | 'left' | 'right'
  /** How many panels the sheet is folded into. More panels, more creases. */
  panels: number
  /** Multiplies the whole timeline. Above 1 is faster. */
  speed: number
  /** Seconds one crease takes to open. */
  unfold: number
  /** Seconds one crease takes to close. */
  fold: number
  /** Seconds between one crease moving and the next. */
  stagger: number
  /** Paper stock. "custom" applies no preset, leaving your own variables in charge. */
  paper: 'kraft' | 'newsprint' | 'blueprint' | 'ink' | 'custom'
}

const DEFAULTS: FoldAwayOptions = {
  direction: 'bottom',
  panels: 4,
  speed: 1,
  unfold: 0.5,
  fold: 0.42,
  stagger: 0.12,
  paper: 'kraft',
}

/** How dark a panel goes once it has turned away from the light. */
const SHADE = 0.45

const faces = (
  <>
    <div className="fold-face fold-front" />
    <div className="fold-face fold-back" />
  </>
)

/**
 * Builds the panels inside out, so panel 2 ends up wrapping 3, wrapping 4…
 * The base panel never rotates — it is the part of the sheet lying on the edge
 * that everything else folds down onto.
 */
function sheet(panels: number): ReactNode {
  let nested: ReactNode = null
  for (let i = panels; i >= 2; i--) {
    nested = (
      <div key={i} className="fold-band" data-fold={i}>
        {faces}
        {nested}
      </div>
    )
  }
  return (
    <div className="fold-band fold-root">
      {faces}
      {nested}
    </div>
  )
}

/** Document order is outermost crease first, which is also unfolding order. */
const creases = (overlay: HTMLDivElement) =>
  gsap.utils.toArray<HTMLElement>(overlay.querySelectorAll('.fold-band[data-fold]'))

const strip = (overlay: HTMLDivElement) =>
  overlay.querySelector<HTMLElement>('.foldaway-slide')

export const FoldAwayTransition = createTransition<FoldAwayOptions>({
  timeout: 8000,
  defaults: DEFAULTS,

  overlay: (options) => (
    <div
      className={`foldaway fold-${options.direction} paper-${options.paper}`}
      style={{ '--fold-panels': options.panels } as React.CSSProperties}
    >
      <div className="foldaway-rig">
        <div className="foldaway-slide">{sheet(options.panels)}</div>
      </div>
    </div>
  ),

  // Park it folded and just off the edge, which is also where enter() leaves it.
  setup: (overlay) => {
    gsap.set(strip(overlay), { yPercent: 100 })
    gsap.set(creases(overlay), { rotateX: -180, '--fold-shade': SHADE })
  },

  leave: ({ overlay, options, done }) => {
    const tl = gsap.timeline({ onComplete: done })

    tl.to(strip(overlay), { yPercent: 0, duration: 0.4, ease: 'power3.out' })

    // Shallowest crease first — the last fold you made is the first one you open.
    creases(overlay).forEach((crease, i) => {
      const at = 0.28 + i * options.stagger
      tl.to(crease, { rotateX: 0, duration: options.unfold, ease: 'power2.inOut' }, at)
      tl.to(crease, { '--fold-shade': 0, duration: options.unfold, ease: 'power1.out' }, at)
    })

    tl.timeScale(options.speed)
    return () => tl.kill()
  },

  enter: ({ overlay, options, done }) => {
    const tl = gsap.timeline({ onComplete: done })

    // Deepest crease first, so the sheet collapses onto the base panel.
    creases(overlay)
      .reverse()
      .forEach((crease, i) => {
        const at = i * options.stagger
        tl.to(crease, { rotateX: -180, duration: options.fold, ease: 'power2.inOut' }, at)
        tl.to(crease, { '--fold-shade': SHADE, duration: options.fold, ease: 'power1.in' }, at)
      })

    tl.to(strip(overlay), { yPercent: 100, duration: 0.45, ease: 'power2.in' }, '>-0.12')

    tl.timeScale(options.speed)
    return () => tl.kill()
  },
})

'use client'

import { TransitionRouter } from 'next-transition-router'
import { useEffect, useRef, type ReactNode } from 'react'

/** Passed to every phase. Query your own nodes out of `overlay`. */
export type TransitionContext<O> = {
  overlay: HTMLDivElement
  /** Whatever the component was given, merged over the config defaults. */
  options: O
  /** Call when the animation is finished. The navigation waits for this. */
  done: () => void
}

/** A phase may return a cleanup function, called if the phase is interrupted. */
export type Phase<O> = (ctx: TransitionContext<O>) => void | (() => void)

export type TransitionConfig<O> = {
  /**
   * Markup that covers the screen. A function when the markup itself depends on
   * the options; otherwise rendered once and reused for every navigation.
   */
  overlay: ReactNode | ((options: O) => ReactNode)
  /** Values a consumer may override as props. */
  defaults: O
  /** Runs once after mount — measure paths, set starting state. */
  setup?: (overlay: HTMLDivElement, options: O) => void
  /** Plays before the route changes. */
  leave: Phase<O>
  /** Plays after the route changes. */
  enter: Phase<O>
  /**
   * Failsafe. If a phase never calls done() the navigation continues anyway,
   * so a broken animation can never trap someone behind an opaque overlay.
   */
  timeout?: number
}

const DEFAULT_TIMEOUT = 4000

const prefersReducedMotion = () =>
  typeof window !== 'undefined' &&
  window.matchMedia('(prefers-reduced-motion: reduce)').matches

/**
 * Turns a transition config into a drop-in provider.
 *
 *   // app/layout.tsx
 *   <CrayonTransition>{children}</CrayonTransition>
 *
 * Engine-agnostic: the phases can use GSAP, Motion, or raw WAAPI. The core only
 * cares that `done()` eventually gets called.
 */
export function createTransition<O extends object>(config: TransitionConfig<O>) {
  const timeout = config.timeout ?? DEFAULT_TIMEOUT

  return function Transition({
    children,
    ...overrides
  }: { children: ReactNode } & Partial<O>) {
    const ref = useRef<HTMLDivElement>(null)
    const options = { ...config.defaults, ...(overrides as Partial<O>) } as O

    // Phases read this rather than closing over a stale render's options.
    const latest = useRef(options)
    latest.current = options

    useEffect(() => {
      if (ref.current) config.setup?.(ref.current, latest.current)
    }, [])

    const run = (phase: Phase<O>) => (next: () => void) => {
      const overlay = ref.current

      // No overlay yet, or the user asked for less motion — navigate straight through.
      if (!overlay || prefersReducedMotion()) {
        next()
        return
      }

      let settled = false
      const done = () => {
        if (settled) return
        settled = true
        clearTimeout(timer)
        next()
      }
      const timer = setTimeout(() => {
        console.warn(`[transition] phase exceeded ${timeout}ms, continuing`)
        done()
      }, timeout)

      let cleanup: void | (() => void)
      try {
        cleanup = phase({ overlay, options: latest.current, done })
      } catch (error) {
        console.error('[transition] phase threw, continuing', error)
        done()
      }

      return () => {
        clearTimeout(timer)
        settled = true
        cleanup?.()
      }
    }

    return (
      <TransitionRouter auto leave={run(config.leave)} enter={run(config.enter)}>
        <div ref={ref} className="transition-overlay" aria-hidden>
          {typeof config.overlay === 'function' ? config.overlay(options) : config.overlay}
        </div>
        {children}
      </TransitionRouter>
    )
  }
}

/* transitions.css — shared styling for every transition in the registry. */

/* ---------- overlay shell (used by all overlay-type transitions) ---------- */

/*
 * inset:0 sizes to the layout viewport, which excludes the scrollbar — so the
 * overlay is centred on the area the reader actually sees. 100vw would include
 * the scrollbar and push the centre to the right of the content instead.
 */
.transition-overlay {
  position: fixed;
  inset: 0;
  z-index: 100;
  pointer-events: none;
}

.transition-overlay svg {
  display: block;
  width: 100%;
  height: 100%;
}

/* ---------- crayon ---------- */

:root {
  --crayon-1: #ff2d87;
  --crayon-2: #aaff00;
  --crayon-3: #0066ff;
}

.crayon {
  position: absolute;
  inset: 0;
  /* Overscaled so strokes drawn near the edges still cover the corners. */
  transform: scale(1.5);
}

/* Hidden until the first leave phase measures the real path lengths. */
.crayon path {
  stroke-dasharray: 99999;
  stroke-dashoffset: 99999;
}

/* ---------- zipper ---------- */

/*
 * Every colour in the artwork reads from these, so overriding them anywhere
 * above the transition recolours the whole zip. Set your own values, or put one
 * of the preset classes below on any ancestor.
 */
:root {
  --zip-metal-hi: #ffffff;
  --zip-metal: #d7d2c8;
  --zip-metal-mid: #8f887c;
  --zip-metal-lo: #4a453e;
  --zip-metal-edge: #211f1c;
  --zip-tape: #3d3d46;
  --zip-tape-lo: #26262c;
}

.zip-steel {
  --zip-metal-hi: #f8fbfe;
  --zip-metal: #c3ced8;
  --zip-metal-mid: #7c8894;
  --zip-metal-lo: #3f4750;
  --zip-metal-edge: #171b20;
  --zip-tape: #2b313a;
  --zip-tape-lo: #191d23;
}

.zip-brass {
  --zip-metal-hi: #fff8dd;
  --zip-metal: #eccb6f;
  --zip-metal-mid: #b8912f;
  --zip-metal-lo: #6b5115;
  --zip-metal-edge: #2b2107;
  --zip-tape: #3a3228;
  --zip-tape-lo: #231f18;
}

.zip-gunmetal {
  --zip-metal-hi: #c6ccd4;
  --zip-metal: #848b95;
  --zip-metal-mid: #4f555d;
  --zip-metal-lo: #2a2d33;
  --zip-metal-edge: #101216;
  --zip-tape: #1f2228;
  --zip-tape-lo: #121418;
}

.zip-copper {
  --zip-metal-hi: #ffe9d6;
  --zip-metal: #e2a179;
  --zip-metal-mid: #a95f37;
  --zip-metal-lo: #5d3018;
  --zip-metal-edge: #23110a;
  --zip-tape: #332822;
  --zip-tape-lo: #1d1714;
}

.zip-rig {
  position: relative;
  height: 100%;
  width: 100%;
  overflow: hidden;
}

.zip-panel {
  position: absolute;
  top: 0;
  bottom: 0;
  width: 50%;
}

.zip-band {
  position: absolute;
  width: 100%;
  overflow: hidden;
}

.zip-band-art {
  position: absolute;
}

.zip-slider-layer {
  position: absolute;
  inset: 0;
  height: 100%;
  width: 100%;
  pointer-events: none;
}

.zip-fill {
  height: 100%;
  width: 100%;
}

@media (prefers-reduced-motion: reduce) {
  .zip-rig { display: none }
}

/* ---------- film burn ---------- */

/*
 * The fire is its own colour, not the pages'. The outgoing page is masked away
 * inside the burn front, the incoming page is masked to show only inside a
 * slightly smaller front, and this ramp sits behind both — so what you see in
 * the gap between them is the fire itself.
 *
 * The ramp is anchored to the band rather than the origin. Anchored to the
 * origin, the visible annulus samples the cold end of the gradient once the
 * front is halfway out, and the fire goes dull.
 */
:root,
.burn-ember {
  --burn-core: #fff4dc;
  --burn-hot: #ffb32e;
  --burn-mid: #d94a12;
  --burn-edge: #6b1806;
}

/* Magnesium burns brilliant white and almost colourless — the point of it is
   that there is no hue, so this stays neutral all the way down. */
.burn-magnesium {
  --burn-core: #ffffff;
  --burn-hot: #f6f7f8;
  --burn-mid: #a9aeb4;
  --burn-edge: #34383d;
}

.burn-cold {
  --burn-core: #ddf5ff;
  --burn-hot: #33c9ff;
  --burn-mid: #0a5fd4;
  --burn-edge: #04123f;
}

.burn-toxic {
  --burn-core: #f4ffd9;
  --burn-hot: #c6ff3d;
  --burn-mid: #46b81a;
  --burn-edge: #0d3a0a;
}

.vt-film-burn::view-transition-group(root) {
  animation: none;
  background:
    radial-gradient(
      circle at var(--burn-x, 50%) var(--burn-y, 50%),
      var(--burn-core) calc(var(--burn-cut, 0px) - var(--burn-band, 64px)),
      var(--burn-hot) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.68),
      var(--burn-mid) calc(var(--burn-cut, 0px) - var(--burn-band, 64px) * 0.3),
      var(--burn-edge) var(--burn-cut, 0px),
      var(--burn-edge) 100%
    );
}

.vt-film-burn::view-transition-image-pair(root) {
  isolation: auto;
}

/* The browser stacks the incoming snapshot above the outgoing one, so the
   outgoing page has to be lifted for its mask to read as a hole rather than as
   nothing at all. */
.vt-film-burn::view-transition-new(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 1;
  mask: url(#burn-mask-new);
  -webkit-mask: url(#burn-mask-new);
}

.vt-film-burn::view-transition-old(root) {
  animation: none;
  mix-blend-mode: normal;
  z-index: 2;
  mask: url(#burn-mask-old);
  -webkit-mask: url(#burn-mask-old);
}

/* ---------- riser ---------- */

/*
 * Nothing here is driven from JavaScript. The outgoing page is pushed back and
 * dimmed, the incoming page is unmasked over it, and the browser runs both off
 * the stylesheet — which is why this one needs no dependencies at all.
 */
.vt-riser::view-transition-group(root) {
  animation: none;
}

.vt-riser::view-transition-image-pair(root) {
  isolation: auto;
}

/*
 * Origin at the arriving edge, not the centre. Scaling about the centre pulls
 * the outgoing page away from that edge, so it reads as sliding off rather than
 * settling behind. Anchored to the edge it recedes into the space the incoming
 * page is about to occupy, and stays visible above it the whole way.
 */
.vt-riser::view-transition-old(root) {
  animation: riser-recede var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 1;
  transform-origin: var(--riser-origin, 50% 0%);
}

/*
 * The incoming page slides in as a card rather than being clipped into view. A
 * clip reveal has no edge and casts nothing, so there is no cue that one page
 * is above the other — the shadow is what actually sells the layering.
 */
.vt-riser::view-transition-new(root) {
  animation: riser-arrive var(--vt-duration, 0.7s) cubic-bezier(0.76, 0, 0.24, 1) both;
  mix-blend-mode: normal;
  z-index: 2;
  box-shadow: var(--riser-shadow, 0 -24px 60px rgba(0, 0, 0, 0.45));
}

/* The tilt is what makes it read as depth rather than a shrink — the page
   leans away from you as it drops back. */
/*
 * Perspective distance matters as much as the angle. At 1400px a 6deg lean
 * narrows the far edge by about 6%, which reads as nothing at all; 900px and
 * 14deg takes it to 80%, which is unmistakably a page leaning away.
 */
@keyframes riser-recede {
  to {
    opacity: var(--riser-dim, 0.35);
    transform: perspective(var(--riser-perspective, 800px))
      translate3d(var(--riser-out-x, 0), var(--riser-out-y, -8vh), 0)
      rotateX(var(--riser-tilt-x, 18deg)) rotateY(var(--riser-tilt-y, 0deg))
      scale(var(--riser-depth, 0.82));
  }
}

@keyframes riser-arrive {
  from {
    transform: translate3d(var(--riser-in-x, 0), var(--riser-in-y, 100%), 0);
  }
  to {
    transform: translate3d(0, 0, 0);
  }
}

/* The incoming page is unmasked from the edge it arrives at, and the outgoing
   page recedes the opposite way, so the two read as one movement. */
.riser-up {
  --riser-in-y: 100%;
  --riser-in-x: 0;
  --riser-shadow: 0 -24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 0%;
  --riser-out-y: calc(var(--riser-travel, 8vh) * -1);
  --riser-out-x: 0;
  --riser-tilt-x: var(--riser-tilt, 18deg);
  --riser-tilt-y: 0deg;
}

.riser-down {
  --riser-in-y: -100%;
  --riser-in-x: 0;
  --riser-shadow: 0 24px 60px rgba(0,0,0,.45);
  --riser-origin: 50% 100%;
  --riser-out-y: var(--riser-travel, 8vh);
  --riser-out-x: 0;
  --riser-tilt-x: calc(var(--riser-tilt, 18deg) * -1);
  --riser-tilt-y: 0deg;
}

.riser-left {
  --riser-in-y: 0;
  --riser-in-x: 100%;
  --riser-shadow: -24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 0% 50%;
  --riser-out-x: calc(var(--riser-travel-x, 8vw) * -1);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: calc(var(--riser-tilt, 18deg) * -1);
}

.riser-right {
  --riser-in-y: 0;
  --riser-in-x: -100%;
  --riser-shadow: 24px 0 60px rgba(0,0,0,.45);
  --riser-origin: 100% 50%;
  --riser-out-x: var(--riser-travel-x, 8vw);
  --riser-out-y: 0;
  --riser-tilt-x: 0deg;
  --riser-tilt-y: var(--riser-tilt, 18deg);
}

@media (prefers-reduced-motion: reduce) {
  .vt-riser::view-transition-old(root),
  .vt-riser::view-transition-new(root) {
    animation: none;
  }
}

/* ---------- fold-away ---------- */

:root {
  --fold-paper: #d8c9ad;
  --fold-paper-back: #bfae8e;
  --fold-crease: rgba(60, 44, 20, 0.22);
  --fold-shadow-color: 28 20 8;
}

/*
 * perspective lives here and preserve-3d one level down, so clipping the
 * overhang on a turned rig cannot flatten the fold.
 */
.foldaway {
  position: absolute;
  inset: 0;
  overflow: clip;
  perspective: 1500px;
  perspective-origin: 50% 50%;
}

/*
 * The fold is always built as horizontal bands collapsing onto the bottom edge.
 * Pointing it at another edge turns the whole rig rather than rebuilding the
 * geometry — the lighting turns with it, which is what you want anyway.
 */
.foldaway-rig {
  position: absolute;
  top: 50%;
  left: 50%;
  width: 100%;
  height: 100%;
  transform: translate(-50%, -50%) rotate(var(--fold-turn, 0deg));
  transform-style: preserve-3d;
}

.fold-bottom { --fold-turn: 0deg; }
.fold-top    { --fold-turn: 180deg; }
.fold-left   { --fold-turn: 90deg; }
.fold-right  { --fold-turn: -90deg; }

/* Turned a quarter, the rig's axes swap — it needs the viewport's other side. */
.fold-left .foldaway-rig,
.fold-right .foldaway-rig {
  width: 100vh;
  height: 100vw;
}

.foldaway-slide {
  position: absolute;
  inset: 0;
  transform-style: preserve-3d;
}

.fold-band {
  position: absolute;
  left: 0;
  right: 0;
  transform-style: preserve-3d;
}

/* The part of the sheet lying on the edge. Everything else folds onto it. */
.fold-root {
  bottom: 0;
  height: calc(100% / var(--fold-panels, 4));
}

/* Each crease hinges off the top edge of the panel below it. */
.fold-band[data-fold] {
  bottom: 100%;
  height: 100%;
  transform-origin: 50% 100%;
}

/*
 * At rest the shade is 0, so the sheet reads as one continuous piece of paper
 * with faint creases. All the directional lighting rides on --fold-shade, which
 * is animated alongside the rotation — that is what stops a spread sheet from
 * looking like a stack of stripes.
 */
.fold-face {
  position: absolute;
  inset: 0;
  backface-visibility: hidden;
  background:
    repeating-linear-gradient(92deg, rgba(0, 0, 0, 0.014) 0 2px, transparent 2px 5px),
    var(--fold-paper);
  box-shadow:
    inset 0 2px 0 -1px rgba(255, 255, 255, 0.22),
    inset 0 -3px 4px -2px var(--fold-crease),
    0 22px 48px -14px rgb(var(--fold-shadow-color) / calc(var(--fold-shade, 0) * 1.6));
}

.fold-back {
  transform: rotateX(180deg);
  background:
    repeating-linear-gradient(92deg, rgba(0, 0, 0, 0.02) 0 2px, transparent 2px 5px),
    var(--fold-paper-back);
}

/*
 * The lit hinge and the dark leading edge. Because the back face is flipped,
 * "to top" points the other way in world space — which is exactly right, since
 * a turned panel's leading edge is at the opposite end.
 */
.fold-face::after {
  content: '';
  position: absolute;
  inset: 0;
  background: linear-gradient(
    to top,
    rgb(var(--fold-shadow-color) / 0.12),
    rgb(var(--fold-shadow-color) / 0.95)
  );
  opacity: var(--fold-shade, 0);
}

.paper-kraft {
  --fold-paper: #d8c9ad;
  --fold-paper-back: #bfae8e;
  --fold-crease: rgba(60, 44, 20, 0.22);
  --fold-shadow-color: 28 20 8;
}

.paper-newsprint {
  --fold-paper: #e9e5db;
  --fold-paper-back: #d0cabc;
  --fold-crease: rgba(40, 38, 32, 0.2);
  --fold-shadow-color: 22 21 18;
}

.paper-blueprint {
  --fold-paper: #1f4470;
  --fold-paper-back: #17334f;
  --fold-crease: rgba(0, 0, 0, 0.4);
  --fold-shadow-color: 3 10 20;
}

.paper-ink {
  --fold-paper: #26242a;
  --fold-paper-back: #1a181d;
  --fold-crease: rgba(0, 0, 0, 0.55);
  --fold-shadow-color: 0 0 0;
}
